CREATE TABLE r AS SELECT matchinfo(t4,'p') AS m1,matchinfo(t4,'c') AS m2,matchinfo(t4,'x') AS m3,matchinfo(t4,'n') AS m4,matchinfo(t4,'l') AS m5,matchinfo(t4,'a') AS m6,matchinfo(t4,'s') AS m7,matchinfo(t4,'xxxxxxxxxxxxxxxxxx') AS m8,matchinfo(t4,'pcx') AS m9,matchinfo(t4,'xpc') AS m10,matchinfo(t4,'ccc') AS m11,matchinfo(t4,'pppxpcpcx') AS m12,matchinfo(t4,'laxnpc') AS m13,matchinfo(t4,'sxsxs') AS m14 FROM t4 WHERE t4 MATCH '"g h i"' ORDER BY rowid